class Solution {
    public int minOperations(int[] nums, int[] numsDivide) {
        int g = 0;
        for (int x : numsDivide) g = gcd(g, x);
        Arrays.sort(nums);
        for (int i = 0; i < nums.length; i++)
            if (g % nums[i] == 0) return i;
        return -1;
    }
    private int gcd(int a, int b) { return b == 0 ? a : gcd(b, a % b); }
}

