    const gcd = (a, b) => b === 0 ? a : gcd(b, a % b);
    let g = 0;
    for (const x of numsDivide) g = gcd(g, x);
    nums.sort((a, b) => a - b);
    for (let i = 0; i < nums.length; i++)
        if (g % nums[i] === 0) return i;
    return -1;
};
